import json, re, sys
out = sys.argv[1]
CITE = re.compile(r'§\d+(?:\.\d+)?|D-\d{3}|Appendix [A-D]')
rows = [
 ("## 1. Introduction", "## 1. Introduction", "X", None),
 ("Purpose.", "#### Purpose", "R", "R2"),
 ("Redstone is a framework for modeling and simulating hierarchical hybrid causal systems (models that mix continuous dynamics, periodic discrete dynamics and events, exchanging values through directed ports).", None, "F", None),
 ("Its home domain is aircraft guidance, navigation and control: vehicle dynamics, sensors and avionics, simulated offline or interactively in real time.", None, "F", None),
 ("The formalism itself is domain-neutral.", None, "F", None),
 ("Capabilities.", "#### Capabilities", "R", "R2"),
 ("A model is written as a tree of components in plain Julia.", "An author writes a tree of components (the units of modeling) in plain Julia.", "F", None),
 ("The build checks the tree.", None, "F", None),
 ("A simulation runs a `Model` (the tree compiled at one scalar type, ready to step) (§9).", None, "F", None),
 ("The framework provides these capabilities.", None, "X", None),
 ("Continuous dynamics with algebraic outputs, integrated on a fixed step, with events either located by root-finding or checked at step boundaries (§2, §10).", None, "F", None),
 ("Multi-rate periodic discrete dynamics at declared sample times, held zero-order between ticks (§3.2, §10.5).", None, "F", None),
 ("A build that derives the execution order from declared feedthrough and rejects algebraic loops by naming the cycle (§5, §9).", None, "F", None),
 ("A runtime periphery (the devices, GUI and scripts that exchange data with a running simulation) that writes by staging and reads by snapshot (§11, §12).", None, "F", None),
 ("An input trace that replays any run bit-identically (§11.5).", None, "F", None),
 ("Stopped-sim services for initialization, trim and linearization, with exact automatic-differentiation Jacobians (§14).", None, "F", None),
 ("Design criteria.", "#### Design criteria", "R", "R2"),
 ("The design answers to five criteria.", None, "F", None),
 ("Wherever it admits a capability it does not build, that capability is weighed against them as a guarded addition.", "It weighs each guarded addition (a capability it admits but does not build) against them.", "F", None),
 ("Zero-allocation stepping and type stability.", None, "R", "R2"),
 ("The inner loop allocates nothing, and the test suite asserts it (§7.5, §9.7).", "The continuous hot path allocates nothing, and CI asserts it (§7.5, §9.7).", "R", "R14"),
 ("Real-time interactive operation.", None, "R", "R2"),
 ("A simulation runs paced against the wall clock, with devices and a GUI attached (§10.7, §11).", None, "F", None),
 ("Live introspection.", None, "R", "R2"),
 ("Every published signal can be inspected by path, during a run and after it (§11.2).", None, "F", None),
 ("Compositional flexibility.", None, "R", "R2"),
 ("Components compose hierarchically, and a component substitutes for another behind the same declared contract (§6, §8).", None, "F", None),
 ("Rigor and error locality.", None, "R", "R2"),
 ("Structure is declared and checked at build time, so a mistake fails where it was made, with a diagnostic naming it (§8.4, §13).", None, "F", None),
 ("Components are plain Julia with no macro DSL, so debugging, tooling and comprehension work on the language's own terms (§8.1).", "Components are plain Julia with no macro DSL (domain-specific language), so debugging, tooling and comprehension work on the language's own terms (§8.1).", "F", None),
 ("Origins.", "#### Origins", "R", "R2"),
 ("Redstone began as a replacement for `FlightCore`, the simulation core of the Flight.jl package.", None, "F", None),
 ("Flight.jl also holds `FlightPhysics`, its physics library, and `FlightApps`, its applications.", None, "F", None),
 ("The early design read those two packages as its requirements.", None, "F", None),
 ("Every capability they demonstrated had to survive, and none of their interfaces had to.", None, "F", None),
 ("Older entries in the decision log reason against `FlightCore` and cite that code,", "Older entries in the decision log (`decisions.md`) reason against `FlightCore` and cite that code.", "F", None),
 ("and the case studies that tested the design against it live in `companions/flight_case_studies.md`.", "The case studies that tested the design against that code live in `companions/flight_case_studies.md`.", "F", None),
 ("Redstone itself does not depend on Flight.jl.", None, "F", None),
 ("Scope of this document.", "#### Scope of this document", "R", "R2"),
 ("This document is the normative statement of the design.", None, "F", None),
 ("It states what the framework is, in the present tense.", None, "F", None),
 ("Part I fixes the formalism and the component model.", None, "F", None),
 ("Part II covers authoring and the build, Part III execution and the runtime periphery, and Part IV failure handling and the stopped-sim services.", None, "F", None),
 ("The appendices index the author-facing contracts, the API, the diagnostic kinds and the vocabulary.", None, "F", None),
 ("`pending.md` registers what the implementation still owes this document and the questions the design leaves open.", "`pending.md` records what the implementation still owes this document and the questions the design leaves open.", "F", None),
 ("It also lists the release work this document does not ask for.", None, "F", None),
 ("The explainers in `companions/` are not normative, and this document wins wherever they disagree.", None, "F", None),
 ("Decision rationale lives in `decisions.md`, including the alternatives considered and the reasons they were rejected.", None, "F", None),
 ("This document cites it throughout as linked `D-nnn` entries, one entry per settled decision.", None, "F", None),
 ("Entry numbers are stable and never reused, so a citation here always names the same entry there.", None, "F", None),
]
claims = []
for i, (o, n, tag, rul) in enumerate(rows, 1):
    c = {"id": f"C-{i:03d}", "old": o, "new": n if n is not None else o, "where": "new",
         "cites": CITE.findall(o), "tag": tag}
    if rul: c["ruling"] = rul
    claims.append(c)
json.dump({"claims": claims, "added": ["(the units of modeling)", "(`decisions.md`)", "(domain-specific language)"]}, open(out, "w"), indent=1, ensure_ascii=False)
